}
.small b {	
       background:transparent none repeat scroll 0 0;
       border-bottom:1px solid #AAAAAA;
       color:black;
       font-weight:normal;
       font-size: 150%;
       margin:0;
       padding-bottom:0.17em;
      display: block;

}
.small span {
  position: absolute;
  top: 7px;
  right: 10px;
}

div#Toc {	
margin-top: 5px;
}
p 
{
       margin:0.4em 0 0.5em;
       font-size:9pt;
}

table
{
       font-size:9pt;
}



/*Links  */

a {
       background:transparent none repeat scroll 0 0;
       color:#002BB8;
       text-decoration:none;
}

a:hover {
       text-decoration:underline;
}
a.unknownlink {
       color:#CC2200;
}
a.anchorlink {
  font-weight: normal;
 font-size: 13px
}
a.unknownlink:hover {
 color: #D9671E;
 text-decoration: underline;
}
a.externallink {
 background-image: url('Default/Images/Wiki/ExternalLink.gif');
 background-position: right;
 background-repeat: no-repeat;
 padding-right: 14px;
}

/*Lists*/
ol, ul {
       list-style-image:none;
       margin:0.3em 0 0 3em;
       padding:0;
}

li {
       margin-bottom:0.6em;
}

ol.wikinumlist dl.wikidefn dd.wikidefn 
{
  margin:0 0 0 0;
}

ul.wikibulletlist dl.wikidefn dd.wikidefn 
{
  margin:0 0 0 0;
}


ol.wikinumlist li.wikibullet dl.wikidefn dd.wikidefn dl.wikidefn dd.wikidefn 
{
 margin:0.3em 0 0 3em;
        padding-top:10px;
}

ul.wikibulletlist  li.wikibullet dl.wikidefn dd.wikidefn dl.wikidefn dd.wikidefn 
{
 margin:0.3em 0 0 3em;
}


/*Headers*/

.editsectionlink {
       float:right;
       margin-top:0.6em;
       margin-left:0.6em;
}

h1, h2, h3, h4, h5, h6 {
       background:transparent none repeat scroll 0 0;
       border-bottom:1px solid #AAAAAA;
       color:black;
       font-weight:normal;
       margin:0;
       padding-bottom:0.17em;
       padding-top:1.2em;
}

h1.pagetitle {
       font-size:188%;
       line-height:1.1em;
       margin-bottom:0.4em;
       padding-bottom:0.17;
       padding-top:0;
}

.legend {
        font-size:90%;
        margin-bottom:1.0em;
}

h1.wikiH1 {
       font-size:150%;
       margin-bottom:0.6em;
}

div.sH1
{
       margin-left: 2em;
}

h2.wikiH2 {
       font-size:125%;
       font-weight:bold;
       margin-bottom:0.3em;
}

div.sH2
{
       margin-left: 2em; 
}

h3.wikiH3 {
       font-size:100%;
       font-weight:bold;
       padding-bottom:0em;
       border-bottom:medium none;
}

div.sH3
{
       margin-left: 0;     
}

h4.wikiH4 {
       font-size:95%;
       font-weight:bold;
       margin-bottom:0em;
       border-bottom:medium none;
}

div.sH4
{
       margin-left: 0; 
}



/*Images */
img {
 border: none;
}

img.image {
 border: solid 1px #CCCCCC;
}
img.format {
 border: solid 1px;
 padding: 2px;
}

img.fileimg
{
 height: 16px;
 vertical-align: middle;
 margin-right: 5px;
}

div.imagedescription {
 font-size: 8pt;
 font-style: italic;
 margin-top: 0.3em;
}

div.clear {
 clear: both;
}

div.imageleft {
 margin-left: 0px;
 margin-right: 8px;
 margin-top: 4px;
 margin-bottom: 4px;
 float: left;
 clear: left;
}

div.imageright {
 margin-left: 8px;
 margin-right: 0px;
 margin-top: 4px;
 margin-bottom: 4px;
 float: right;
 clear: right;
}

div.imagecenter 
{
 width: 98%;
 text-align: center;
}

table.imageauto {
 border: solid 1px #CCCCCC;
 background-color: #F9F9F9;
 margin: 0.8em 0em 0.8em 0em;
 padding: 4px;
 clear: both;
}

td.imageauto {
 background-color: #F9F9F9;
}

/*Toc */
.TocBox {
    /*   background-color:#F5F7F8; */
       border-radius: 10px;
       position: relative;
       padding:5px;
       width:100%
}

/* Code, Pre */

code {
 font-family: Courier New, Lucida Console, Monospace;
        background-color: #F0F0FF; 
        padding-left:0.3em;
        padding-right:0.3em;
}

pre {
 font-family: Courier New, Lucida Console, Monospace;
        line-height:1.2em;  
 padding: 0.4em;
 margin: 0.8em 0em 0.8em 0em;
 border: dashed 1px #CCCCCC;
        background-color: #F0F0FF; 
}

.source-highlighted {background-color: #F0F0FF;}
.source-highlighted .nu { color: brown; }
.source-highlighted .kw { color: blue; }
.source-highlighted .cmt { color: green; }
.source-highlighted .sl { color: brown; }
.source-highlighted .br { color: darkgreen; }
.source-highlighted .add { background: palegreen; }
.source-highlighted .del { background: pink; }


/*Tables*/
.GrayBox {
 border: solid 1px #CCCCCC;
 background-color:  #F9F9F9;
 margin: 0.8em 0em 0.8em 0em;
        padding: 0.4em 0.4em 0.4em 0em;
}

.GrayBoxContent
{
}

table.GrayBoxContent td.hintcell{
 vertical-align: top;
        width:24px;
        padding: 0.6em 0.6em 0.6em 0.6em;
       background-color: #F9F9F9;
}

table.GrayBoxContent td.warncell {
 vertical-align: top;
        padding: 0.6em 0.6em 0.6em 0.6em;
       background-color: #F9F9F9;
}

table.GrayBoxContent td.boxcontent
{    
       background-color: #F9F9F9;
}

table.checklist
{
       background-color:#AAAAAA;  
       border-spacing: 1px;
       empty-cells:show;
       margin:1em 0 1em 0;
}

table.checklist th
{
       padding:0.2em 0.4em;
       background-color: #EEEEEE;
       border: 0px solid #FFFFFF;
       color: #000000;
       font-weight: bold;
}
table.checklist td
{
       padding: 0.6em 0.6em 0.6em 0.8em;
       background-color: #FFFFFF;
       color: #000000;
       vertical-align: top;
}

table.GrayBox td
{
 background-color:  #F9F9F9;
}

table#listtable
{
        background-color:#FFFFFF;
}

table.listtable th
{
       font-size: 14px;
       padding: 2px 2px 2px 6px;
       background-color: #9A9A9A;
       border: 0px solid #FFFFFF;
       color: #FFFFFF;
       font-weight: bold;
}

table.listtable td
{
       padding: 0.6em 0.6em 0.6em 0.6em;
}

table.listtable tr.oddline
{
       background-color: #F0F0F0;
}

table.listtable td.boldcol
{
       font-weight: bold;
       vertical-align: top;
}

/* Rounded tables displayed in articles */

.hinttabletop {
  background:  url(Default/Images/Wiki/hinttable.gif) no-repeat scroll 0 -6px;
  font-size:0;
  height:6px;
  margin:0 auto;
  width:180px;
}

.hinttablebottom {
  background:  url(Default/Images/Wiki/hinttable.gif) no-repeat scroll 0 0px;
  font-size:0;
  height:6px;
  margin:0 auto;
  width:180px;
}

.contenttablehead
{
  background-color: #9A9A9A;
  border: 1px solid #FFFFFF;
  color: #FFFFFF;
  font-weight: bold;
}

.contenttableheadtd
{
  padding: 8px 5px 8px 5px;
}

.contenttabletd
{
  margin: 0px;
  padding: 2px 2px 2px 6px;
  vertical-align: top;
  vertical-align: top;
}

.contenttabletdfirst
{
  font-weight: bold;
  vertical-align: top;
  padding: 2px 2px 2px 6px;
}

.contenttabletrfirst
{
  background-color: #F0F0F0;
}

.contenttableproduct
{
  padding: 0px;
  margin: 0px;
  vertical-align: top;
}

/*Nested Topics*/
.chapter > ul { 
margin-left: 0em;
}
.chapter > ul > li {
position: relative;
bottom: -7px;
}
.chapter > ul > li > a {
font-size: 14px;
}
